package com.example.starter.ros.service;

import java.util.List;

/**
 * 资源变更事件负载定义,JSON 序列化后写入 node_event.payload。
 */
public final class EventPayloads {

    private EventPayloads() {
    }

    /**
     * 资源条目(事件负载与检查点共用)。
     */
    public record ResourceItem(String category, String fqName, String interfaceType) {
    }

    /**
     * 节点注册事件负载。
     */
    public record RegisteredPayload(
            String nodeId,
            String namespace,
            String nodeName,
            String state,
            long version,
            List<ResourceItem> resources
    ) {
    }

    /**
     * 生命周期状态迁移事件负载。
     */
    public record StateChangedPayload(
            String nodeId,
            String fromState,
            String toState,
            long version
    ) {
    }

    /**
     * 主动注销事件负载。
     */
    public record DeregisteredPayload(String nodeId) {
    }

    /**
     * 异常退出事件负载,携带被同事务清理的全部资源。
     */
    public record CrashedPayload(
            String nodeId,
            List<ResourceItem> cleanedResources
    ) {
    }
}

package com.example.starter.ros.service;

import com.example.starter.ros.web.dto.ResourceSpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 请求参数规范化与 SHA-256 摘要工具,用于识别同参/异参重放。
 */
public final class RequestHasher {

    private RequestHasher() {
    }

    /**
     * 注册请求的规范化参数(不含 requestId),资源按类别/全限定名/接口类型排序。
     */
    public static Map<String, Object> registerParams(String nodeId, String namespace,
                                                     String nodeName,
                                                     List<ResourceSpec> resources) {
        List<ResourceSpec> sorted = new ArrayList<>(resources);
        sorted.sort(Comparator.comparing(ResourceSpec::category)
                .thenComparing(ResourceSpec::name)
                .thenComparing(ResourceSpec::interfaceType));
        List<Map<String, String>> resourceList = new ArrayList<>();
        for (ResourceSpec spec : sorted) {
            Map<String, String> item = new LinkedHashMap<>();
            item.put("category", spec.category().trim().toUpperCase());
            item.put("name", spec.name());
            item.put("interfaceType", spec.interfaceType());
            resourceList.add(item);
        }
        Map<String, Object> params = new LinkedHashMap<>();
        params.put("nodeId", nodeId);
        params.put("namespace", namespace);
        params.put("nodeName", nodeName);
        params.put("resources", resourceList);
        return params;
    }

    /**
     * 状态迁移请求的规范化参数。
     */
    public static Map<String, Object> transitionParams(String nodeId, String targetState,
                                                       long expectedVersion) {
        Map<String, Object> params = new LinkedHashMap<>();
        params.put("nodeId", nodeId);
        params.put("targetState", targetState.trim().toUpperCase());
        params.put("expectedVersion", expectedVersion);
        return params;
    }

    /**
     * 仅含节点ID的操作(注销/异常退出/恢复)的规范化参数。
     */
    public static Map<String, Object> nodeParams(String nodeId) {
        Map<String, Object> params = new LinkedHashMap<>();
        params.put("nodeId", nodeId);
        return params;
    }

    /**
     * 计算规范化参数的 SHA-256 十六进制摘要。
     */
    public static String sha256(String normalized) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] bytes = digest.digest(normalized.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(bytes.length * 2);
            for (byte b : bytes) {
                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
                sb.append(Character.forDigit(b & 0xF, 16));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("当前JVM不支持SHA-256", e);
        }
    }
}

package com.example.starter.ros.support;

/**
 * ROS 名称规范化:相对名与节点命名空间拼接为以 / 开头的全限定名称。
 * 不接入真实 rclcpp/rclpy 名称重映射,仅模拟常用拼接规则。
 */
public final class RosNames {

    private RosNames() {
    }

    /**
     * 计算资源全限定名称。
     * 以 / 开头的名称视为全局限定名直接规范化;其余与节点命名空间拼接。
     * 结果以单个 / 开头,不含连续斜杠或尾部斜杠。
     */
    public static String fullyQualifiedName(String namespace, String resourceName) {
        String ns = normalizeNamespace(namespace);
        String name = normalizeSegments(resourceName);
        if (resourceName.trim().startsWith("/")) {
            return "/" + name;
        }
        return "/".equals(ns) ? "/" + name : ns + "/" + name;
    }

    /**
     * 规范化命名空间,结果为 / 或 /a/b 形式。
     */
    public static String normalizeNamespace(String namespace) {
        if (namespace == null || namespace.isBlank()) {
            return "/";
        }
        String segments = normalizeSegments(namespace);
        return segments.isEmpty() ? "/" : "/" + segments;
    }

    private static String normalizeSegments(String raw) {
        String[] parts = raw.trim().split("/");
        StringBuilder sb = new StringBuilder();
        for (String part : parts) {
            if (part.isEmpty()) {
                continue;
            }
            if (!sb.isEmpty()) {
                sb.append('/');
            }
            sb.append(part);
        }
        return sb.toString();
    }
}

