    void redundantSlashesAreCollapsed() {
        assertThat(RosNames.fullyQualifiedName("//robot//", "/service//add"))
                .isEqualTo("/service/add");
        assertThat(RosNames.normalizeNamespace("//ns//sub//")).isEqualTo("/ns/sub");
    }
}

