file.content:
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

// 兼容项:本机工作目录含非 ASCII 字符(中文),Windows 上 Gradle 测试 worker 的
// @argfile 按系统 ANSI 代码页解析,含中文路径的 classpath 会被破坏,导致
// "找不到主类 worker.org.gradle.process.internal.worker.GradleWorkerMain"。
// 将构建输出重定向到 ASCII 临时路径可消除该问题;测试报告/结果在 test 后
// 复制回本 worktree 的 build/ 标准位置归档。源码与资源始终保留在 worktree 内。
def asciiTempRoot = System.getenv('TEMP') ?: System.getProperty('java.io.tmpdir')
layout.buildDirectory = file("${asciiTempRoot}/ros-registry-build-B")

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'com.h2database:h2'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('test') {
    useJUnitPlatform()

    // 本环境 GRADLE_USER_HOME 位于含中文的 worktree 内,测试 worker 的长 classpath
    // 通过 @argfile 传递时会被 Windows JVM launcher 按 GBK 误解析而找不到主类。
    // 执行前把所有含非 ASCII 路径的 classpath 条目复制到 ASCII 临时目录并重映射。
    def asciiCpRoot = file("${asciiTempRoot}/ros-registry-cp-B")
    doFirst {
        asciiCpRoot.mkdirs()
        def mapped = []
        classpath.files.eachWithIndex { f, idx ->
            def ascii = f.absolutePath.chars().allMatch { it < 128 as char }
            if (ascii) {
                mapped << f
                return
            }
            def target = new File(asciiCpRoot, String.format('%03d-%s', idx, f.name))
            if (f.isDirectory()) {
                target.mkdirs()
                copy { from f; into target }
            } else if (!target.exists() || target.length() != f.length()) {
                java.nio.file.Files.copy(f.toPath(), target.toPath(),
                        java.nio.file.StandardCopyOption.REPLACE_EXISTING)
            }
            mapped << target
        }
        classpath = files(mapped)

        def diag2 = layout.projectDirectory.file('build/worker-diag2.txt').asFile
        diag2.parentFile.mkdirs()
        def remaining = classpath.files.findAll { f ->
            !f.absolutePath.chars().allMatch { it < 128 as char }
        }
        diag2.text = 'nonAsciiRemaining=' + remaining.size() + '\n' +
                classpath.files.collect { it.absolutePath }.join('\n')
    }

    // Windows 中文工作目录下测试 worker 的 @argfile 默认按系统 ANSI 编码(GBK)解析,
    // 通过 JDK_JAVA_OPTIONS 在 launcher 解析参数文件前切换为 UTF-8,
    // 避免 worker 启动期 ClassNotFoundException: GradleWorkerMain。
    environment 'JDK_JAVA_OPTIONS', '-Dfile.encoding=UTF-8 -Dsun.jnu.encoding=UTF-8'
    jvmArgs '-Dfile.encoding=UTF-8', '-Dsun.jnu.encoding=UTF-8'

    // 构建输出位于 ASCII 临时目录(见 layout.buildDirectory);测试完成后把
    // JUnit XML 结果与 HTML 报告复制回本 worktree 的标准 build/ 位置归档。
    doLast {
        def archiveRoot = layout.projectDirectory.dir('build')
        copy {
            from(layout.buildDirectory.dir('test-results/test'))
            into(archiveRoot.dir('test-results/test'))
        }
        copy {
            from(layout.buildDirectory.dir('reports/tests/test'))
            into(archiveRoot.dir('reports/tests/test'))
        }
    }
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}

