    @Test
    void conflictErrorCodesAreMachineReadable() throws Exception {
        mockMvc.perform(post("/api/ros/nodes")
                        .contentType(MediaType.APPLICATION_JSON).content("""
                                {"nodeId":"n1","namespace":"/ns","nodeName":"a",
                                 "resources":[],"requestId":"r1"}
                                """))
